import 'dart:convert';
import 'package:uuid/uuid.dart';
import 'package:dio/dio.dart';
import 'auth_repository.dart';
import '../local/gestock_database.dart';

class SupplierRepository {
  SupplierRepository(this.db,this.auth,{Dio? dio}) : _dio=dio??Dio(BaseOptions(baseUrl:const String.fromEnvironment('GESTOCK_API_URL',defaultValue:'https://gestock-api.ccds22431.workers.dev'),headers:{'Content-Type':'application/json'}));
  final GeStockDatabase db; final AuthRepository auth; final Dio _dio; final _uuid=const Uuid();
  Future<List<Map<String,Object?>>> list(String businessId,{String query=''}) async {final d=await db.database;final q=query.trim();if(q.isEmpty)return d.query('suppliers',where:'business_id=?',whereArgs:[businessId],orderBy:'name COLLATE NOCASE');return d.query('suppliers',where:'business_id=? AND (name LIKE ? OR phone LIKE ? OR email LIKE ?)',whereArgs:[businessId,'%$q%','%$q%','%$q%'],orderBy:'name COLLATE NOCASE');}
  Future<void> pullCloud(String businessId) async {final token=await auth.getAccessToken();final r=await _dio.get('/v1/suppliers',queryParameters:{'business_id':businessId},options:Options(headers:{'Authorization':'Bearer $token'}));if(r.data is! Map||r.data['data'] is! List)throw StateError('Réponse fournisseurs invalide');final d=await db.database;final now=DateTime.now().toUtc().toIso8601String();await d.transaction((txn)async{for(final raw in (r.data['data'] as List).whereType<Map>()){final x=Map<String,Object?>.from(raw);final id=x['id']?.toString();if(id==null)continue;final pending=await txn.query('outbox',where:"entity_type='supplier' AND entity_id=? AND status IN ('queued','failed','conflict')",whereArgs:[id],limit:1);if(pending.isNotEmpty)continue;final existing=await txn.query('suppliers',where:'id=?',whereArgs:[id],limit:1);final values={'id':id,'business_id':businessId,'name':x['name']??'','phone':x['phone'],'email':x['email'],'address':x['address'],'notes':x['notes'],'created_at':x['created_at']??now,'updated_at':x['updated_at']??now,'sync_state':'synced'};if(existing.isEmpty)await txn.insert('suppliers',values);else await txn.update('suppliers',values,where:'id=?',whereArgs:[id]);}});}
  Future<void> create({required String businessId,required String name,String phone='',String email='',String address='',String notes=''}) async {if(name.trim().isEmpty)throw ArgumentError('Le nom du fournisseur est obligatoire.');final d=await db.database;final id=_uuid.v4();final now=DateTime.now().toUtc().toIso8601String();final payload={'id':id,'business_id':businessId,'name':name.trim(),'phone':phone.trim().isEmpty?null:phone.trim(),'email':email.trim().isEmpty?null:email.trim(),'address':address.trim().isEmpty?null:address.trim(),'notes':notes.trim().isEmpty?null:notes.trim(),'created_at':now,'updated_at':now};await d.transaction((txn)async{await txn.insert('suppliers',{...payload,'sync_state':'pending'});await txn.insert('outbox',{'id':id,'business_id':businessId,'entity_type':'supplier','entity_id':id,'operation':'upsert','payload':jsonEncode(payload),'created_at':now,'attempts':0,'status':'queued'});});}
  Future<void> update({required String businessId,required String supplierId,required String name,String phone='',String email='',String address='',String notes=''}) async {if(name.trim().isEmpty)throw ArgumentError('Le nom du fournisseur est obligatoire.');final d=await db.database;final now=DateTime.now().toUtc().toIso8601String();final rows=await d.query('suppliers',where:'id=? AND business_id=?',whereArgs:[supplierId,businessId],limit:1);if(rows.isEmpty)throw StateError('Fournisseur introuvable.');final payload={'id':supplierId,'business_id':businessId,'name':name.trim(),'phone':phone.trim().isEmpty?null:phone.trim(),'email':email.trim().isEmpty?null:email.trim(),'address':address.trim().isEmpty?null:address.trim(),'notes':notes.trim().isEmpty?null:notes.trim(),'created_at':rows.first['created_at'],'updated_at':now};await d.transaction((txn)async{await txn.update('suppliers',{...payload,'sync_state':'pending'},where:'id=?',whereArgs:[supplierId]);final pending=await txn.query('outbox',where:"entity_type='supplier' AND entity_id=? AND status IN ('queued','failed','conflict')",whereArgs:[supplierId],limit:1);if(pending.isNotEmpty)await txn.update('outbox',{'payload':jsonEncode(payload),'created_at':now,'status':'queued','attempts':0},where:'id=?',whereArgs:[pending.first['id']]);else await txn.insert('outbox',{'id':_uuid.v4(),'business_id':businessId,'entity_type':'supplier','entity_id':supplierId,'operation':'upsert','payload':jsonEncode(payload),'created_at':now,'attempts':0,'status':'queued'});});}
}
